//
// Implements all service methods from the Technical Specification v0.2.
// Traceability:
//   R1-R3,R9-R11 → AskQuestion, QueryNotebook, ListNotebooks, GetHealth, SetupAuth
//   R4-R6        → CreateNotebook, BatchCreateNotebooks, AddFolder, AddSource, ListSources, RemoveSource
//   R7,R12-R15   → GenerateDataTable, GeminiQuery, GetToolProfile, Doctor, GetQueryHistory
service CognitiveToolService {
  rpc AddFolder ( .operation.cognitive.v1.AddFolderRequest ) returns ( .operation.cognitive.v1.AddFolderResponse );
  // Source ops (R5-R6)
  rpc AddSource ( .operation.cognitive.v1.AddSourceRequest ) returns ( .operation.cognitive.v1.AddSourceResponse );
  // Core querying (R1)
  rpc AskQuestion ( .operation.cognitive.v1.AskQuestionRequest ) returns ( .operation.cognitive.v1.AskQuestionResponse );
  rpc BatchCreateNotebooks ( .operation.cognitive.v1.BatchCreateNotebooksRequest ) returns ( .operation.cognitive.v1.BatchCreateNotebooksResponse );
  // Notebook lifecycle (R4-R5)
  rpc CreateNotebook ( .operation.cognitive.v1.CreateNotebookRequest ) returns ( .operation.cognitive.v1.CreateNotebookResponse );
  // Diagnostics (R15)
  rpc Doctor ( .operation.cognitive.v1.DoctorRequest ) returns ( .operation.cognitive.v1.DoctorResponse );
  // Gemini fallback (R12)
  rpc GeminiQuery ( .operation.cognitive.v1.GeminiQueryRequest ) returns ( .operation.cognitive.v1.GeminiQueryResponse );
  // Advanced outputs (R7)
  rpc GenerateDataTable ( .operation.cognitive.v1.GenerateDataTableRequest ) returns ( .operation.cognitive.v1.GenerateDataTableResponse );
  // Resilience & auth (R9-R11)
  rpc GetHealth ( .operation.cognitive.v1.GetHealthRequest ) returns ( .operation.cognitive.v1.GetHealthResponse );
  rpc GetNotebook ( .operation.cognitive.v1.GetNotebookRequest ) returns ( .operation.cognitive.v1.GetNotebookResponse );
  rpc GetQueryHistory ( .operation.cognitive.v1.GetQueryHistoryRequest ) returns ( .operation.cognitive.v1.GetQueryHistoryResponse );
  rpc GetSourceContent ( .operation.cognitive.v1.GetSourceContentRequest ) returns ( .operation.cognitive.v1.GetSourceContentResponse );
  // Tool profiles (R14)
  rpc GetToolProfile ( .operation.cognitive.v1.GetToolProfileRequest ) returns ( .operation.cognitive.v1.GetToolProfileResponse );
  // Library management (R3)
  rpc ListNotebooks ( .operation.cognitive.v1.ListNotebooksRequest ) returns ( .operation.cognitive.v1.ListNotebooksResponse );
  rpc ListSources ( .operation.cognitive.v1.ListSourcesRequest ) returns ( .operation.cognitive.v1.ListSourcesResponse );
  rpc QueryNotebook ( .operation.cognitive.v1.QueryNotebookRequest ) returns ( .operation.cognitive.v1.QueryNotebookResponse );
