pub fn default_rust_collection_from_env() -> String {
    std::env::var("COGNITIVE_MCP_RUST_COLLECTION")
        .unwrap_or_else(|_| DEFAULT_RUST_SOLO_COLLECTION.to_string())
}

pub fn default_collections_for_mode(mode: RetrievalMode) -> Vec<String> {
    let env_key = match mode {
        RetrievalMode::Completion => "COGNITIVE_MCP_COMPLETION_COLLECTIONS",
        RetrievalMode::Search => "COGNITIVE_MCP_SEARCH_COLLECTIONS",
        RetrievalMode::Deep => "COGNITIVE_MCP_DEEP_COLLECTIONS",
    };

    if let Ok(value) = std::env::var(env_key) {
        let collections = split_collection_list(&value);
        if !collections.is_empty() {
            return collections;
        }
    }

    if let Ok(value) = std::env::var("COGNITIVE_MCP_RAG_COLLECTIONS") {
        let collections = split_collection_list(&value);
        if !collections.is_empty() {
            return collections;
        }
    }

    match mode {
        RetrievalMode::Completion | RetrievalMode::Search => DEFAULT_VOYAGE4_LITE_COLLECTIONS
            .iter()
            .map(|s| (*s).to_string())
            .collect(),
        RetrievalMode::Deep => vec![default_collection_from_env()],
    }
}

#!/usr/bin/env python3
"""
Export rust-analyzer document symbols for rust-lang/rust as JSONL.

This uses the same LSP backend configured for Kiro in:
  /home/jeremy/git/repos/rust-lang/rust/.kiro/settings/lsp.json

Output records are one symbol per line:
  {"file_path": "...", "name": "...", "kind": 12, "line_start": 1, ...}
"""

from __future__ import annotations

import argparse
import json
import os
import queue
import subprocess
import sys
import threading
import time
from pathlib import Path
from typing import Any


GIT_ROOT = Path("/home/jeremy/git")
REPO_ROOT = GIT_ROOT / "repos" / "rust-lang" / "rust"
DEFAULT_OUT = GIT_ROOT / "lsp" / "rust-lang-rust-symbols.jsonl"
KIRO_LSP_CONFIG = REPO_ROOT / ".kiro" / "settings" / "lsp.json"


def uri_for(path: Path) -> str:
    return path.resolve().as_uri()


def git_files(repo_root: Path, limit: int | None = None) -> list[str]:
    files = subprocess.check_output(["git", "ls-files", "*.rs"], cwd=repo_root, text=True).splitlines()
    return files[:limit] if limit else files


class LspClient:
    def __init__(self, command: list[str], cwd: Path):
        self.proc = subprocess.Popen(
            command,
            cwd=cwd,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=False,
        )
        self.next_id = 1
        self.responses: dict[int, Any] = {}
        self.notifications: queue.Queue[Any] = queue.Queue()
        self._lock = threading.Lock()
        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()
        self._stderr = threading.Thread(target=self._stderr_loop, daemon=True)
        self._stderr.start()

    def _stderr_loop(self) -> None:
        assert self.proc.stderr is not None
        for raw in self.proc.stderr:
            line = raw.decode("utf-8", errors="replace").rstrip()
            if line:
                print(f"rust-analyzer: {line}", file=sys.stderr)

    def _read_loop(self) -> None:
        assert self.proc.stdout is not None
        while True:
            headers: dict[str, str] = {}
            while True:
                line = self.proc.stdout.readline()
                if not line:
                    return
                if line in (b"\r\n", b"\n"):
                    break
                key, value = line.decode("ascii", errors="replace").split(":", 1)
                headers[key.lower()] = value.strip()
            length = int(headers.get("content-length", "0"))
            if length <= 0:
                continue
            body = self.proc.stdout.read(length)
            msg = json.loads(body.decode("utf-8"))
            if "id" in msg:
                with self._lock:
                    self.responses[msg["id"]] = msg
            else:
                self.notifications.put(msg)

    def send(self, payload: dict[str, Any]) -> None:
        assert self.proc.stdin is not None
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        header = f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
        self.proc.stdin.write(header + body)
        self.proc.stdin.flush()

    def request(self, method: str, params: Any = None, timeout: float = 120.0) -> Any:
        req_id = self.next_id
        self.next_id += 1
        payload = {"jsonrpc": "2.0", "id": req_id, "method": method}
        if params is not None:
            payload["params"] = params
        self.send(payload)
        deadline = time.time() + timeout
        while time.time() < deadline:
            with self._lock:
                msg = self.responses.pop(req_id, None)
            if msg is not None:
                if "error" in msg:
                    raise RuntimeError(f"{method} failed: {msg['error']}")
                return msg.get("result")
            if self.proc.poll() is not None:
                raise RuntimeError(f"LSP process exited with {self.proc.returncode}")
            time.sleep(0.05)
        raise TimeoutError(f"{method} timed out")

    def notify(self, method: str, params: dict[str, Any]) -> None:
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def close(self) -> None:
        try:
            self.request("shutdown", None, timeout=10)
            self.notify("exit", {})
        finally:
            try:
                self.proc.terminate()
            except ProcessLookupError:
                pass


def flatten_symbols(symbols: list[dict[str, Any]], rel_path: str) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []

    def walk(items: list[dict[str, Any]], parent: str = "") -> None:
        for item in items:
            name = item.get("name", "")
            qualified = f"{parent}::{name}" if parent and name else name
            rng = item.get("range") or item.get("selectionRange") or {}
            start = rng.get("start", {})
            end = rng.get("end", {})
            if name and start and end:
                out.append({
                    "file_path": rel_path,
                    "name": name,
                    "qualified_name": qualified,
                    "kind": item.get("kind"),
                    "line_start": int(start.get("line", 0)) + 1,
                    "line_end": int(end.get("line", 0)) + 1,
                    "character_start": int(start.get("character", 0)),
                    "character_end": int(end.get("character", 0)),
                })
            children = item.get("children") or []
            if children:
                walk(children, qualified)

    walk(symbols)
    return out


def load_command() -> list[str]:
    if KIRO_LSP_CONFIG.exists():
        data = json.loads(KIRO_LSP_CONFIG.read_text(encoding="utf-8"))
        rust = data.get("languages", {}).get("rust", {})
        command = rust.get("command") or "rust-analyzer"
        args = rust.get("args") or []
        return [command, *args]
    return ["rust-analyzer"]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--limit", type=int, default=0, help="Limit files for testing.")
    parser.add_argument("--timeout", type=float, default=180.0)
    args = parser.parse_args()

    files = git_files(REPO_ROOT, args.limit or None)
    args.out.parent.mkdir(parents=True, exist_ok=True)

    client = LspClient(load_command(), REPO_ROOT)
    try:
        client.request("initialize", {
            "processId": os.getpid(),
            "rootUri": uri_for(REPO_ROOT),
            "workspaceFolders": [{"uri": uri_for(REPO_ROOT), "name": "rust"}],
            "capabilities": {
                "textDocument": {
                    "documentSymbol": {
                        "hierarchicalDocumentSymbolSupport": True,
                    }
                }
            },
        }, timeout=args.timeout)
        client.notify("initialized", {})

        count = 0
        with args.out.open("w", encoding="utf-8") as f:
            for idx, rel_path in enumerate(files, 1):
                abs_path = REPO_ROOT / rel_path
                text = abs_path.read_text(encoding="utf-8", errors="replace")
                uri = uri_for(abs_path)
                client.notify("textDocument/didOpen", {
                    "textDocument": {
                        "uri": uri,
                        "languageId": "rust",
                        "version": 1,
                        "text": text,
                    }
                })
                try:
                    symbols = client.request(
                        "textDocument/documentSymbol",
                        {"textDocument": {"uri": uri}},
                        timeout=args.timeout,
                    ) or []
                    for record in flatten_symbols(symbols, rel_path):
                        f.write(json.dumps(record, separators=(",", ":")) + "\n")
                        count += 1
                finally:
                    client.notify("textDocument/didClose", {"textDocument": {"uri": uri}})
                if idx % 250 == 0:
                    print(f"processed {idx}/{len(files)} files, {count} symbols", file=sys.stderr)
        print(f"wrote {count} symbols to {args.out}")
        return 0
    finally:
        client.close()


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import json
import logging
import os
import re
import subprocess
import sys
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, Iterator


ROOT = Path("/home/jeremy/git")
REPOS = ROOT / "repos"
STATE_DIR = ROOT / "logs" / "vector-state"
DEFAULT_MODEL = "voyage-4-lite"
DEFAULT_DIMENSION = 1024
DEFAULT_BATCH_SIZE = 24
DEFAULT_CHUNK_CHARS = 12_000
DEFAULT_OVERLAP_CHARS = 800
DEFAULT_MAX_FILE_BYTES = 1_500_000
EX_TEMPFAIL = 75

INCLUDE_EXTS = {
    ".rs", ".go", ".py", ".ts", ".tsx", ".js", ".jsx", ".java",
    ".c", ".h", ".cc", ".cpp", ".cxx", ".hpp", ".hh",
    ".proto", ".toml", ".json", ".yaml", ".yml", ".md", ".rst",
    ".txt", ".sh", ".sql", ".rego", ".cue", ".xml",
}

SKIP_PARTS = {
    ".git", "target", "node_modules", "dist", "build", ".venv",
    "__pycache__", ".mypy_cache", ".pytest_cache", ".gradle", ".idea",
}


@dataclass(frozen=True)
class Chunk:
    repo: str
    rel_path: str
    abs_path: Path
    text: str
    chunk_index: int
    line_start: int
    line_end: int
    char_start: int
    char_end: int
    file_sha256: str
    language: str


def run_git(repo_root: Path, args: list[str]) -> str:
    return subprocess.check_output(["git", *args], cwd=repo_root, text=True).strip()


def git_files(repo_root: Path) -> list[str]:
    try:
        return run_git(repo_root, ["ls-files"]).splitlines()
    except Exception:
        return [
            str(path.relative_to(repo_root))
            for path in repo_root.rglob("*")
            if path.is_file() and ".git" not in path.parts
        ]


def git_meta(repo_root: Path) -> dict[str, str]:
    def maybe(args: list[str]) -> str:
        try:
            return run_git(repo_root, args)
        except Exception:
            return ""
    return {
        "commit": maybe(["rev-parse", "HEAD"]),
        "branch": maybe(["branch", "--show-current"]),
        "remote": maybe(["config", "--get", "remote.origin.url"]),
    }


def language_for(path: str) -> str:
    ext = Path(path).suffix.lower()
    return {
        ".go": "go", ".py": "python", ".ts": "typescript", ".tsx": "typescript",
        ".js": "javascript", ".jsx": "javascript", ".java": "java", ".c": "c",
        ".h": "c-header", ".cc": "cpp", ".cpp": "cpp", ".cxx": "cpp",
        ".hpp": "cpp-header", ".hh": "cpp-header", ".proto": "protobuf",
        ".md": "markdown", ".yaml": "yaml", ".yml": "yaml", ".json": "json",
        ".toml": "toml", ".sh": "shell", ".rego": "rego", ".cue": "cue",
        ".xml": "xml", ".rs": "rust",
    }.get(ext, ext.lstrip(".") or "text")


def slug(value: str) -> str:
    value = re.sub(r"[^a-zA-Z0-9]+", "-", value).strip("-").lower()
    return value or "root"


def should_skip(rel_path: str) -> bool:
    path = Path(rel_path)
    if any(part in SKIP_PARTS for part in path.parts):
        return True
    return path.suffix.lower() not in INCLUDE_EXTS


def line_number_at(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def chunk_text(text: str, chunk_chars: int, overlap_chars: int) -> Iterator[tuple[str, int, int]]:
    if len(text) <= chunk_chars:
        yield text, 0, len(text)
        return
    start = 0
    while start < len(text):
        hard_end = min(start + chunk_chars, len(text))
        end = hard_end
        if hard_end < len(text):
            split = text.rfind("\n\n", start + chunk_chars // 2, hard_end)
            if split == -1:
                split = text.rfind("\n", start + chunk_chars // 2, hard_end)
            if split != -1:
                end = split + 1
        piece = text[start:end].strip()
        if piece:
            yield piece, start, end
        if end >= len(text):
            break
        start = max(0, end - overlap_chars)


def iter_chunks(repo: str, repo_root: Path, args: argparse.Namespace) -> Iterator[Chunk]:
    for rel_path in git_files(repo_root):
        if should_skip(rel_path):
            continue
        abs_path = repo_root / rel_path
        try:
            if abs_path.stat().st_size > args.max_file_bytes:
                continue
            text = abs_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if not text.strip():
            continue
        sha = hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()
        for idx, (chunk, start, end) in enumerate(chunk_text(text, args.chunk_chars, args.overlap_chars)):
            yield Chunk(
                repo=repo,
                rel_path=rel_path,
                abs_path=abs_path,
                text=chunk,
                chunk_index=idx,
                line_start=line_number_at(text, start),
                line_end=line_number_at(text, end),
                char_start=start,
                char_end=end,
                file_sha256=sha,
                language=language_for(rel_path),
            )


def point_id(group: str, chunk: Chunk, commit: str) -> str:
    stable = f"{group}:{chunk.repo}:{commit}:{chunk.rel_path}:{chunk.chunk_index}:{chunk.line_start}:{chunk.line_end}"
    return str(uuid.uuid5(uuid.NAMESPACE_URL, stable))


def payload(group: str, chunk: Chunk, meta: dict[str, str]) -> dict:
    source_url = ""
    if meta.get("remote", "").startswith("https://github.com/") and meta.get("commit"):
        base = meta["remote"].removesuffix(".git")
        source_url = f"{base}/blob/{meta['commit']}/{chunk.rel_path}#L{chunk.line_start}-L{chunk.line_end}"
    subid = f"obs.software.{slug(group)}-{slug(chunk.repo)}-{slug(chunk.rel_path)}.index.chunk-{chunk.chunk_index:04d}@v1"
    return {
        "text": chunk.text,
        "uuid": point_id(group, chunk, meta.get("commit", "")),
        "subid": subid,
        "repo_group": group,
        "repo": chunk.repo,
        "remote": meta.get("remote", ""),
        "branch": meta.get("branch", ""),
        "commit": meta.get("commit", ""),
        "file_path": chunk.rel_path,
        "file_name": Path(chunk.rel_path).name,
        "extension": Path(chunk.rel_path).suffix.lower(),
        "language": chunk.language,
        "chunk_index": chunk.chunk_index,
        "line_start": chunk.line_start,
        "line_end": chunk.line_end,
        "char_start": chunk.char_start,
        "char_end": chunk.char_end,
        "file_sha256": chunk.file_sha256,
        "source_url": source_url,
        "category": "obs",
        "component_type": "software",
        "subject": slug(f"{group}-{chunk.repo}-{chunk.rel_path}"),
        "verb": "index",
        "facet": f"chunk-{chunk.chunk_index:04d}",
        "version": 1,
        "control_refs": [],
        "statement_refs": [],
        "kiro_lsp": {
            "state_dir": str(ROOT / "logs" / "kiro-lsp-state"),
            "expected_done_file": f"{group}.{chunk.repo.replace('/', '__')}.done",
        },
        "mouseover": {
            "title": f"{chunk.repo}:{chunk.rel_path}:{chunk.line_start}",
            "subtitle": chunk.language,
            "detail": next((line.strip()[:220] for line in chunk.text.splitlines() if line.strip()), ""),
            "source_range": f"{chunk.rel_path}:{chunk.line_start}-{chunk.line_end}",
            "subid": subid,
        },
    }


def estimate_tokens(text: str) -> int:
    return max(1, len(text) // 4)


def batch_tokens(batch: list[Chunk]) -> int:
    return sum(estimate_tokens(chunk.text) for chunk in batch)


def read_token_budget(path: Path | None) -> int:
    if path is None or not path.exists():
        return 0
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return 0
    return int(payload.get("used_tokens", 0))


def write_token_budget(path: Path | None, used_tokens: int, max_tokens: int | None) -> None:
    if path is None:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(
            {
                "used_tokens": used_tokens,
                "max_tokens": max_tokens,
                "updated_at": time.time(),
            },
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def batched(items: Iterable[Chunk], size: int) -> Iterator[list[Chunk]]:
    batch: list[Chunk] = []
    for item in items:
        batch.append(item)
        if len(batch) >= size:
            yield batch
            batch = []
    if batch:
        yield batch


def is_rate_limit(exc: Exception) -> bool:
    msg = str(exc).lower()
    return "rate limit" in msg or "too many requests" in msg or "429" in msg


def is_batch_too_large(exc: Exception) -> bool:
    msg = str(exc).lower()
    return "max allowed tokens" in msg or "lower the number of tokens" in msg


def is_transient_qdrant_error(exc: Exception) -> bool:
    msg = str(exc).lower()
    return (
        "timed out" in msg
        or "readtimeout" in msg
        or "connecttimeout" in msg
        or "connection refused" in msg
        or "temporarily unavailable" in msg
        or "resource temporarily unavailable" in msg
    )


def import_clients():
    try:
        import voyageai
        from qdrant_client import QdrantClient
        from qdrant_client.models import Distance, PointStruct, VectorParams
    except ImportError as exc:
        raise SystemExit(f"Missing dependency: {exc}") from exc
    return voyageai, QdrantClient, Distance, PointStruct, VectorParams


def ensure_collection(client, collection: str, dimension: int, Distance, VectorParams) -> None:
    if not client.collection_exists(collection):
        client.create_collection(
            collection_name=collection,
            vectors_config=VectorParams(size=dimension, distance=Distance.COSINE),
        )
    for field in ["uuid", "subid", "repo_group", "repo", "language", "file_path", "category", "component_type"]:
        try:
            client.create_payload_index(collection, field_name=field, field_schema="keyword")
        except Exception:
            pass


def read_repos(list_file: Path) -> list[str]:
    return [
        line.strip()
        for line in list_file.read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.strip().startswith("#")
    ]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--group", required=True)
    parser.add_argument("--list-file", type=Path, required=True)
    parser.add_argument("--collection", required=True)
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--dimension", type=int, default=DEFAULT_DIMENSION)
    parser.add_argument("--batch-size", type=int, default=DEFAULT_BATCH_SIZE)
    parser.add_argument("--chunk-chars", type=int, default=DEFAULT_CHUNK_CHARS)
    parser.add_argument("--overlap-chars", type=int, default=DEFAULT_OVERLAP_CHARS)
    parser.add_argument("--max-file-bytes", type=int, default=DEFAULT_MAX_FILE_BYTES)
    parser.add_argument("--qdrant-url", default="http://localhost:6333")
    parser.add_argument("--qdrant-timeout", type=int, default=120)
    parser.add_argument(
        "--max-input-tokens",
        type=int,
        default=0,
        help="Stop before embedding a batch that would exceed this estimated input-token budget.",
    )
    parser.add_argument(
        "--token-budget-file",
        type=Path,
        help="JSON state file for sharing the estimated input-token budget across sequential runs.",
    )
    args = parser.parse_args()

    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    if not os.environ.get("VOYAGE_API_KEY"):
        raise SystemExit("VOYAGE_API_KEY missing")

    STATE_DIR.mkdir(parents=True, exist_ok=True)
    voyageai, QdrantClient, Distance, PointStruct, VectorParams = import_clients()
    voyage = voyageai.Client()
    qdrant = QdrantClient(url=args.qdrant_url, timeout=args.qdrant_timeout)
    ensure_collection(qdrant, args.collection, args.dimension, Distance, VectorParams)
    max_input_tokens = args.max_input_tokens or None
    used_input_tokens = read_token_budget(args.token_budget_file)
    if max_input_tokens is not None:
        logging.info(
            "token budget enabled used=%s max=%s remaining=%s",
            used_input_tokens,
            max_input_tokens,
            max(0, max_input_tokens - used_input_tokens),
        )

    def qdrant_upsert_with_retry(points: list, depth: int = 0) -> None:
        try:
            qdrant.upsert(
                collection_name=args.collection,
                points=points,
                wait=False,
                timeout=args.qdrant_timeout,
            )
            return
        except Exception as exc:
            if is_transient_qdrant_error(exc) and depth < 8:
                sleep_s = min(120, 5 * (2 ** depth))
                logging.warning("qdrant upsert transient failure; sleeping %ss: %s", sleep_s, exc)
                time.sleep(sleep_s)
                qdrant_upsert_with_retry(points, depth + 1)
                return
            raise

    def upsert_batch(batch: list[Chunk], meta_by_repo: dict[str, dict[str, str]], depth: int = 0) -> int:
        nonlocal used_input_tokens
        estimated = batch_tokens(batch)
        if max_input_tokens is not None and used_input_tokens + estimated > max_input_tokens:
            remaining = max_input_tokens - used_input_tokens
            logging.warning(
                "token budget exhausted before request group=%s collection=%s used=%s estimated_batch=%s remaining=%s",
                args.group,
                args.collection,
                used_input_tokens,
                estimated,
                remaining,
            )
            raise SystemExit(EX_TEMPFAIL)
        try:
            result = voyage.embed(
                [c.text for c in batch],
                model=args.model,
                input_type="document",
                output_dimension=args.dimension,
            )
        except Exception as exc:
            if is_batch_too_large(exc) and len(batch) > 1:
                mid = len(batch) // 2
                logging.warning("splitting oversized batch size=%s: %s", len(batch), exc)
                return upsert_batch(batch[:mid], meta_by_repo, depth + 1) + upsert_batch(batch[mid:], meta_by_repo, depth + 1)
            if is_rate_limit(exc):
                sleep_s = min(1800, 60 * (2 ** min(depth, 5)))
                logging.warning("rate limited; sleeping %ss: %s", sleep_s, exc)
                time.sleep(sleep_s)
                return upsert_batch(batch, meta_by_repo, depth + 1)
            raise
        used_input_tokens += estimated
        write_token_budget(args.token_budget_file, used_input_tokens, max_input_tokens)

        points = []
        for chunk, vector in zip(batch, result.embeddings):
            meta = meta_by_repo[chunk.repo]
            points.append(PointStruct(
                id=point_id(args.group, chunk, meta.get("commit", "")),
                vector=vector,
                payload=payload(args.group, chunk, meta),
            ))
        qdrant_upsert_with_retry(points)
        return len(points)

    total = 0
    for repo in read_repos(args.list_file):
        repo_root = REPOS / repo
        if not repo_root.is_dir():
            logging.warning("missing repo: %s", repo)
            continue
        done = STATE_DIR / f"{args.group}.{repo.replace('/', '__')}.done"
        if done.exists():
            logging.info("skip done repo=%s", repo)
            continue
        meta = git_meta(repo_root)
        meta_by_repo = {repo: meta}
        repo_total = 0
        for batch in batched(iter_chunks(repo, repo_root, args), args.batch_size):
            repo_total += upsert_batch(batch, meta_by_repo)
            total += len(batch)
            if repo_total % (args.batch_size * 10) == 0:
                logging.info("group=%s repo=%s upserted=%s total=%s", args.group, repo, repo_total, total)
        done.write_text(json.dumps({"repo": repo, "chunks": repo_total, "finished_at": time.time()}) + "\n")
        logging.info("done group=%s repo=%s chunks=%s", args.group, repo, repo_total)
    logging.info("complete group=%s total=%s", args.group, total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

