class KeyPool:
    """Rotates Voyage API keys by REAL token usage.

    Voyage's free quota returns NO error when exhausted (it silently keeps
    serving — i.e. starts billing), so an error-based failover is useless. The
    only safe stop is a local budget driven by the *actual* tokens Voyage
    reports (`response.usage.total_tokens`). When a key reaches its budget we
    rotate to the next key; when all keys are exhausted we stop (EX_TEMPFAIL).
    """

    def __init__(self, voyageai, specs: list[tuple[str, int]], budget_file: Path | None):
        self.voyageai = voyageai
        self.budget_file = budget_file
        self.specs: list[dict] = []
        for env_name, budget in specs:
            val = os.environ.get(env_name, "").strip()
            if not val:
                raise SystemExit(f"key env {env_name} not set")
            self.specs.append({"name": env_name, "key": val, "budget": int(budget)})
        self.used: dict[str, int] = self._load()
        self.clients: dict[str, object] = {}
        self.idx = 0

    def _load(self) -> dict[str, int]:
        if self.budget_file and self.budget_file.exists():
            try:
                d = json.loads(self.budget_file.read_text(encoding="utf-8"))
                return {k: int(v) for k, v in d.get("used_by_key", {}).items()}
            except Exception:
                pass
        return {}

    def _save(self) -> None:
        if not self.budget_file:
            return
        self.budget_file.parent.mkdir(parents=True, exist_ok=True)
        self.budget_file.write_text(json.dumps({
            "used_by_key": self.used,
            "budgets": {s["name"]: s["budget"] for s in self.specs},
            "updated_at": time.time(),
        }, sort_keys=True) + "\n", encoding="utf-8")

    def remaining(self) -> int:
        return sum(max(0, s["budget"] - self.used.get(s["name"], 0)) for s in self.specs)

    def _pick(self, need: int) -> dict:
        while self.idx < len(self.specs):
            s = self.specs[self.idx]
            if self.used.get(s["name"], 0) + need <= s["budget"]:
                return s
            logging.warning("key %s budget reached (used=%s budget=%s) -> rotating to next",
                            s["name"], self.used.get(s["name"], 0), s["budget"])
            self.idx += 1
        logging.error("all keys exhausted; stopping (resumable)")
        raise SystemExit(EX_TEMPFAIL)

    def embed(self, texts: list[str], est_tokens: int, model: str, dim: int):
        s = self._pick(est_tokens)
        if s["name"] not in self.clients:
            self.clients[s["name"]] = self.voyageai.Client(api_key=s["key"])
        result = self.clients[s["name"]].embed(
            texts, model=model, input_type="document", output_dimension=dim)
        self.used[s["name"]] = self.used.get(s["name"], 0) + int(result.total_tokens)
        self._save()
        return result

