87	///     #[serde(default)]
88	///     pub enabled: bool,
89	///     #[secret]
90	///     pub bot_token: String,
91	///     #[secret]
92	///     pub webhook_secret: Option<String>,
93	///     pub room_id: String,
94	/// }
95	/// ```
96	///
97	/// 2. If the struct nests inside a parent (e.g. `ChannelsConfig`), add `#[nested]`
98	///    on the parent's field so the tree traversal finds it.
