/// Test-only: assert a derived schema preserves the *contract* of a golden
/// hand-rolled reference — field set, recursive types, `required`, and
/// constraints (the parts consumers depend on). Descriptions/defaults/examples
/// are advisory and intentionally not compared.
#[cfg(test)]
pub(crate) fn assert_contract_equal(reference: &PluginSchema, derived: &PluginSchema) {
    assert_eq!(derived.name, reference.name, "plugin name");
    let mut rk: Vec<_> = reference.fields.keys().cloned().collect();
    let mut dk: Vec<_> = derived.fields.keys().cloned().collect();
    rk.sort();
    dk.sort();
    assert_eq!(dk, rk, "[{}] field set differs", reference.name);
    for k in &rk {
        let r = &reference.fields[k];
        let d = &derived.fields[k];
        assert_eq!(
            type_tag(&d.field_type),
            type_tag(&r.field_type),
            "[{}] field `{k}` type differs",
            reference.name
        );
        assert_eq!(d.required, r.required, "[{}] field `{k}` required differs", reference.name);
        assert_eq!(
            constraint_tags(&d.constraints),
            constraint_tags(&r.constraints),
            "[{}] field `{k}` constraints differ",
            reference.name
        );
    }
}

#[cfg(test)]
fn type_tag(t: &FieldType) -> String {
    match t {
        FieldType::String => "string".into(),
        FieldType::Integer => "integer".into(),
        FieldType::Float => "float".into(),
        FieldType::Boolean => "boolean".into(),
        FieldType::Any => "any".into(),
        FieldType::Enum(_) => "enum".into(),
        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
        FieldType::Object(m) => {
            let mut entries: Vec<String> =
                m.iter().map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type))).collect();
            entries.sort();
            format!("object{{{}}}", entries.join(","))
        }
    }
}

